@startuml

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

enum ComparisonResult {
  LOWER
  EQUAL
  HIGHER
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

abstract class Card {
  + id : string
  + height : int
  + compare(other : Card) : ComparisonResult
}

class DiamondCard extends Card {}
class HeartCard extends Card {}
class SpadeCard extends Card {}
class ClubCard extends Card {}

class Deck {
  + id : string
}

class Player {
  + id : string
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
}

class JackRound extends Round {}

class SoloRound extends Round {
  + soloType : SoloType
}

class MandatorySoloRound extends SoloRound {}

class WinningPlayer {
  + id : string
}

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
Game "1" *-- "*" Round
Deck "1" *-- "0..48" Card
ScoringTable "1" *-- "*" Round
Round "1" -- "*" WinningPlayer
SoloRound "1" -- "1" Player : solo player

@enduml

